window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bb8bff00ccede270"]={"versions": [{"id": "FIG-bb8bff00ccede270", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Farb- und Symbollegende zur Visualisierung des FlexRay-Frame-Aufbaus sowie des Abstimmungsmechanismus (NM-Vote) im AUTOSAR FlexRay Network Management (FlexrayNM). Sie definiert die visuelle Kodierung für Frame-Segmente und NM-Zustände innerhalb übergeordneter Diagramme zum dynamischen und statischen Segment.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier Legendenentitäten mit Farbzuordnung:</p>\n<ul class=\"fig-list\">\n<li>Frame Header: Hellgrau/Hellblau hinterlegtes Rechteck mit Rand</li>\n<li>Frame Trailer (CRC): Orange/Pfirsichfarben hinterlegtes Rechteck mit Rand</li>\n<li>Frame Payload (Data): Hellgrün hinterlegtes Rechteck mit Rand</li>\n<li>Vote of Node #: Signalgrün (Vollfarbe) ausgefülltes Rechteck zur Kennzeichnung des NM-Votes eines Knotens</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Zuordnungsvorschrift ohne dynamischen Ablauf. Die Entitäten dienen als Referenzmuster für zeitliche Abläufe oder Slot-Strukturen, in denen die Komponenten eines FlexRay-Frames (Header, Payload, Trailer/CRC) sowie das Übertragen eines NM-Votings durch Knoten visuell differenziert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dokumentationslegende zur Sicherstellung einer einheitlichen Interpretation von FlexRay-NM-Diagrammen. Sie besitzt definitorischen Charakter für die Farbkennzeichnung von Protokollteilen des FlexRay-Rahmens (Header, Nutzdaten, CRC-Trailer) und der Signalisierung des NM-Abstimmungsstatus der Netzwerkknoten.</p>"}, {"id": "FIG-3d936855dc3630bc", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Farb- und Symbollegende zur Visualisierung des FlexRay-Frame-Aufbaus sowie des Abstimmungsmechanismus (NM-Vote) im AUTOSAR FlexRay Network Management (FlexrayNM). Sie definiert die visuelle Kodierung für Frame-Segmente und NM-Zustände innerhalb übergeordneter Diagramme zum dynamischen und statischen Segment.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier Legendenentitäten mit Farbzuordnung:</p>\n<ul class=\"fig-list\">\n<li>Frame Header: Hellgrau/Hellblau hinterlegtes Rechteck mit Rand</li>\n<li>Frame Trailer (CRC): Orange/Pfirsichfarben hinterlegtes Rechteck mit Rand</li>\n<li>Frame Payload (Data): Hellgrün hinterlegtes Rechteck mit Rand</li>\n<li>Vote of Node #: Signalgrün (Vollfarbe) ausgefülltes Rechteck zur Kennzeichnung des NM-Votes eines Knotens</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Zuordnungsvorschrift ohne dynamischen Ablauf. Die Entitäten dienen als Referenzmuster für zeitliche Abläufe oder Slot-Strukturen, in denen die Komponenten eines FlexRay-Frames (Header, Payload, Trailer/CRC) sowie das Übertragen eines NM-Votings durch Knoten visuell differenziert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dokumentationslegende zur Sicherstellung einer einheitlichen Interpretation von FlexRay-NM-Diagrammen. Sie besitzt definitorischen Charakter für die Farbkennzeichnung von Protokollteilen des FlexRay-Rahmens (Header, Nutzdaten, CRC-Trailer) und der Signalisierung des NM-Abstimmungsstatus der Netzwerkknoten.</p>"}, {"id": "FIG-df84e74b9a56b0da", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Farb- und Symbollegende zur Visualisierung des FlexRay-Frame-Aufbaus sowie des Abstimmungsmechanismus (NM-Vote) im AUTOSAR FlexRay Network Management (FlexrayNM). Sie definiert die visuelle Kodierung für Frame-Segmente und NM-Zustände innerhalb übergeordneter Diagramme zum dynamischen und statischen Segment.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier Legendenentitäten mit Farbzuordnung:</p>\n<ul class=\"fig-list\">\n<li>Frame Header: Hellgrau/Hellblau hinterlegtes Rechteck mit Rand</li>\n<li>Frame Trailer (CRC): Orange/Pfirsichfarben hinterlegtes Rechteck mit Rand</li>\n<li>Frame Payload (Data): Hellgrün hinterlegtes Rechteck mit Rand</li>\n<li>Vote of Node #: Signalgrün (Vollfarbe) ausgefülltes Rechteck zur Kennzeichnung des NM-Votes eines Knotens</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Zuordnungsvorschrift ohne dynamischen Ablauf. Die Entitäten dienen als Referenzmuster für zeitliche Abläufe oder Slot-Strukturen, in denen die Komponenten eines FlexRay-Frames (Header, Payload, Trailer/CRC) sowie das Übertragen eines NM-Votings durch Knoten visuell differenziert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dokumentationslegende zur Sicherstellung einer einheitlichen Interpretation von FlexRay-NM-Diagrammen. Sie besitzt definitorischen Charakter für die Farbkennzeichnung von Protokollteilen des FlexRay-Rahmens (Header, Nutzdaten, CRC-Trailer) und der Signalisierung des NM-Abstimmungsstatus der Netzwerkknoten.</p>"}], "trans": [{"from": "FIG-bb8bff00ccede270", "to": "FIG-3d936855dc3630bc", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Legende: Typografie und Skalierung neu gerendert (Pixelabmessungen von 798x117 auf 591x110 verkleinert).</li>\n<li>Bildinhalt: Alle vier Legendeneinträge und Farbfelder sind inhaltlich unverändert vorhanden.</li>\n</ul>"}, {"from": "FIG-3d936855dc3630bc", "to": "FIG-df84e74b9a56b0da", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
